using System;using System.IO;using System.Net.Http;using System.Net.WebSockets;using System.Text;using System.Text.Json;using System.Windows.Forms;using NAudio.Wave;using Whisper.net;
namespace CaiVoiceTransmitter;internal static class Program{[STAThread]static void Main(){ApplicationConfiguration.Initialize();Application.Run(new MainForm());}}
sealed class MainForm:Form{
Label status=new(){AutoSize=true,Text="Whisper offline • Chrome CDP 9222"};TextBox log=new(){Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill};Button start=new(){Text="START OFFLINE WHISPER MIC",Height=44,Dock=DockStyle.Top};WaveInEvent mic;MemoryStream audio=new();bool listening,spoken,busy;DateTime last;string model=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CAIVoice","ggml-base.en.bin");
public MainForm(){Text="Character.AI Offline Voice Transmitter";Width=760;Height=520;var top=new Panel{Dock=DockStyle.Top,Height=95};status.Left=10;status.Top=8;start.Top=40;top.Controls.Add(status);top.Controls.Add(start);Controls.Add(log);Controls.Add(top);start.Click+=async(_,__)=>{if(listening)Stop();else await Start();};FormClosing+=(_,__)=>Stop();}
async Task Start(){try{start.Enabled=false;if(!File.Exists(model)||new FileInfo(model).Length<10000000){Directory.CreateDirectory(Path.GetDirectoryName(model));status.Text="Downloading Whisper base.en (~150MB, one time)…";using var h=new HttpClient();await using var s=await h.GetStreamAsync("https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-base.en.bin");await using var d=File.Create(model);await s.CopyToAsync(d);}audio=new();mic=new WaveInEvent{WaveFormat=new WaveFormat(16000,16,1),BufferMilliseconds=100};mic.DataAvailable+=Data;mic.StartRecording();listening=true;start.Text="STOP MICROPHONE";status.Text="Listening offline… Pause after speaking to send.";Log("Whisper ready. Speak and pause ~1 second.");}catch(Exception e){status.Text=e.Message;Log(e.ToString());}finally{start.Enabled=true;}}
void Data(object o,WaveInEventArgs e){if(!listening)return;audio.Write(e.Buffer,0,e.BytesRecorded);long sum=0;for(int i=0;i<e.BytesRecorded/2;i++){short x=BitConverter.ToInt16(e.Buffer,i*2);sum+=(long)x*x;}double rms=Math.Sqrt(sum/Math.Max(1,e.BytesRecorded/2));if(rms>450){spoken=true;last=DateTime.UtcNow;}if(spoken&&!busy&&DateTime.UtcNow-last>TimeSpan.FromSeconds(1)&&audio.Length>32000){busy=true;byte[] pcm=audio.ToArray();audio.SetLength(0);spoken=false;_=Transcribe(pcm);}}
async Task Transcribe(byte[] pcm){string wav=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".wav");try{using(var w=new WaveFileWriter(wav,new WaveFormat(16000,16,1)))w.Write(pcm,0,pcm.Length);using var fac=WhisperFactory.FromPath(model);using var proc=fac.CreateBuilder().WithLanguage("en").Build();using var fs=File.OpenRead(wav);var b=new StringBuilder();await foreach(var seg in proc.ProcessAsync(fs))b.Append(seg.Text);string text=b.ToString().Trim();if(text.Length>0){Log("WHISPER: "+text);string result=await Send(text);Log("CAI: "+result);status.Text=result;}}catch(Exception e){Log("WHISPER ERROR: "+e.Message);status.Text="Whisper error";}finally{try{File.Delete(wav);}catch{}busy=false;}}
async Task<string> Send(string text){using var h=new HttpClient();var a=JsonDocument.Parse(await h.GetStringAsync("http://127.0.0.1:9222/json"));var p=a.RootElement.EnumerateArray().FirstOrDefault(x=>x.TryGetProperty("type",out var t)&&t.GetString()=="page"&&x.TryGetProperty("url",out var u)&&(u.GetString()??"").Contains("character.ai",StringComparison.OrdinalIgnoreCase));if(p.ValueKind==JsonValueKind.Undefined)return "Open Character.AI in Chrome Debug port 9222";using var ws=new ClientWebSocket();await ws.ConnectAsync(new Uri(p.GetProperty("webSocketDebuggerUrl").GetString()),default);string j="""(()=>{let t="""+JsonSerializer.Serialize(text)+""";let b=[...document.querySelectorAll('textarea,input,[contenteditable=true],[role=textbox]')].filter(e=>e.getClientRects().length).at(-1);if(!b)return 'INPUT_NOT_FOUND';b.focus();if(b.matches('input,textarea')){let d=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(b),'value');d?.set?d.set.call(b,t):b.value=t}else b.textContent=t;b.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:t}));let f=b.closest('form'),s=f?.querySelector('button[type=submit]');if(s&&!s.disabled)s.click();else b.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',keyCode:13,which:13,bubbles:true}));return 'SENT'})()""";string r=await Eval(ws,j);if(r!="SENT"){await ws.CloseAsync(WebSocketCloseStatus.NormalClosure,"",default);return r;}r=await Eval(ws,"""(async()=>{let d='M9.576 2.534C7.578 1.299 5 2.737 5 5.086v13.828c0 2.35 2.578 3.787 4.576 2.552l11.194-6.914c1.899-1.172 1.899-3.932 0-5.104z';for(let i=0;i<100;i++){await new Promise(r=>setTimeout(r,500));let p=[...document.querySelectorAll('path')].filter(x=>x.getAttribute('d')===d&&x.getClientRects().length).at(-1);if(p&&!document.querySelector('[data-testid*=stop-generating],button[aria-label*=stop i]')&&i>5){(p.closest('button,[role=button]')||p.parentElement.closest('button,[role=button]'))?.click();return 'Played reply';}}return 'Play button not found'})()""");await ws.CloseAsync(WebSocketCloseStatus.NormalClosure,"",default);return r;}
async Task<string> Eval(ClientWebSocket w,string x){await w.SendAsync(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(new{id=1,method="Runtime.evaluate",@params=new{expression=x,returnByValue=true,awaitPromise=true}})),WebSocketMessageType.Text,true,default);byte[] z=new byte[65536];while(true){var n=await w.ReceiveAsync(z,default);using var d=JsonDocument.Parse(Encoding.UTF8.GetString(z,0,n.Count));if(!d.RootElement.TryGetProperty("id",out var i)||i.GetInt32()!=1)continue;var q=d.RootElement.GetProperty("result").GetProperty("result");return q.TryGetProperty("value",out var v)?v.GetString()??"": "CDP error";}}
void Stop(){listening=false;try{mic?.StopRecording();mic?.Dispose();}catch{}mic=null;start.Text="START OFFLINE WHISPER MIC";status.Text="Stopped";}void Log(string s){if(!IsDisposed)BeginInvoke(()=>log.AppendText(s+Environment.NewLine));}
